object Encrypt0d000721 {
  def main(args: Array[String]): Unit = {
    val plain = "0d000721"
    val l1 = plain.reverse
    val xored = l1.map(c => (c.toByte ^ 0x5A).toByte)
    val l3 = xored.map(b => f"${b}%02x").mkString
    val l4 = java.util.Base64.getEncoder.encodeToString(l3.getBytes("UTF-8"))
    println(l4.reverse)
  }
}
